332	    fn open_window(
333	        &self,
334	        handle: AnyWindowHandle,
335	        params: WindowParams,
336	    ) -> anyhow::Result<Box<dyn PlatformWindow>> {
337	        match &params.kind {
338	            WindowKind::Normal => {}
339	            WindowKind::AnchoredPopup(_) => return Err(PopupNotSupportedError.into()),
340	            WindowKind::PopUp => {
341	                return Err(WebWindowError::UnsupportedWindowKind("popup windows").into());
342	            }
343	            WindowKind::Floating => {
344	                return Err(WebWindowError::UnsupportedWindowKind("floating windows").into());
345	            }
346	            WindowKind::Dialog => {
347	                return Err(WebWindowError::UnsupportedWindowKind("dialog windows").into());
348	            }
349	        }
350	
351	        match self.window_lifecycle.get() {
352	            WebWindowLifecycle::Open => return Err(WebWindowError::AlreadyOpen.into()),
353	            WebWindowLifecycle::Closed => {
354	                return Err(WebWindowError::ReopeningUnsupported.into());
355	            }
356	            WebWindowLifecycle::Unavailable => {
357	                return Err(WebWindowError::GraphicsUnavailable.into());
358	            }
359	            WebWindowLifecycle::Available => {}
360	        }
361	
362	        let context_ref = self.wgpu_context.borrow();
363	        let context = context_ref
364	            .as_ref()
365	            .ok_or(WebWindowError::GraphicsInitializationPending)?;
366	        let prepared_window = self
367	            .prepared_window
368	            .borrow_mut()
369	            .take()
370	            .ok_or(WebWindowError::GraphicsInitializationPending)?;
371	        let canvas = prepared_window.canvas;
372	        let canvas_for_cleanup = canvas.clone();
373	
374	        let window = WebWindow::new(
375	            handle,
376	            params,
377	            context,
378	            canvas,
379	            prepared_window.surface,
380	            self.browser_window.clone(),
381	            self.window_lifecycle.clone(),
382	            self.active_window.clone(),
383	        );
384	        match window {
385	            Ok(window) => {
386	                self.window_lifecycle.set(WebWindowLifecycle::Open);
387	                *self.active_window.borrow_mut() = Some(handle);
388	                Ok(Box::new(window))
389	            }
390	            Err(error) => {
391	                let canvas: &web_sys::Element = canvas_for_cleanup.as_ref();
392	                canvas.remove();
393	                self.window_lifecycle.set(WebWindowLifecycle::Unavailable);
394	                Err(error)
395	            }
396	        }
397	    }
