559	    fn read_from_clipboard_async(&self) -> Task<Result<Option<ClipboardItem>, ClipboardReadError>> {
560	        let navigator = self.browser_window.navigator();
561	        // `navigator.clipboard` is undefined outside secure contexts; probing
562	        // first avoids a wasm-bindgen abort from invoking a method on
563	        // `undefined`.
564	        let clipboard_available = js_sys::Reflect::get(navigator.as_ref(), &"clipboard".into())
565	            .is_ok_and(|clipboard| !clipboard.is_undefined() && !clipboard.is_null());
566	        if !clipboard_available {
567	            return Task::ready(Err(ClipboardReadError::Unavailable));
568	        }
569	        // `read()` must be called synchronously so it is still covered by the
570	        // user activation (e.g. the click on a context-menu item) that
571	        // triggered this read.
572	        let read = navigator.clipboard().read();
573	        self.foreground_executor.spawn(async move {
574	            let items = wasm_bindgen_futures::JsFuture::from(read)
575	                .await
576	                .map_err(clipboard_read_rejection_error)?;
577	            let mut entries = Vec::new();
578	            let mut saw_unsupported_type = false;
579	            for item in js_sys::Array::from(&items).iter() {
580	                let item: web_sys::ClipboardItem = item.unchecked_into();
581	                for mime_type in item.types().iter() {
582	                    let Some(mime_type) = mime_type.as_string() else {
583	                        continue;
584	                    };
585	                    // Only fetch blobs for types we can convert; copies from
586	                    // other web apps routinely carry `text/html` and
587	                    // `web application/...` custom formats whose `getType`
588	                    // fetches would be wasted or rejected.
589	                    if mime_type == "text/plain" {
590	                        match read_clipboard_item_text(&item, &mime_type).await {
591	                            Ok(text) if !text.is_empty() => {
592	                                entries.push(ClipboardEntry::String(ClipboardString::new(text)));
593	                            }
594	                            Ok(_) => {}
595	                            Err(error) => log_clipboard_entry_error(&mime_type, &error),
596	                        }
597	                    } else if let Some(format) = ImageFormat::from_mime_type(&mime_type) {
598	                        match read_clipboard_item_bytes(&item, &mime_type).await {
599	                            Ok(bytes) => {
600	                                entries
601	                                    .push(ClipboardEntry::Image(Image::from_bytes(format, bytes)));
602	                            }
603	                            Err(error) => log_clipboard_entry_error(&mime_type, &error),
604	                        }
605	                    } else {
606	                        saw_unsupported_type = true;
607	                    }
608	                }
609	            }
610	            if !entries.is_empty() {
611	                Ok(Some(ClipboardItem { entries }))
612	            } else if saw_unsupported_type {
613	                Err(ClipboardReadError::UnsupportedContent)
614	            } else {
615	                Ok(None)
616	            }
617	        })
618	    }
619	
620	    fn write_to_clipboard(&self, item: ClipboardItem) {
621	        if let Some(text) = item.text()
622	            && let Some(window) = web_sys::window()
623	        {
624	            // Fire-and-forget; called synchronously inside the user's input
625	            // event, which satisfies the browser's user-activation requirement.
626	            drop(window.navigator().clipboard().write_text(&text));
627	        }
628	    }
629	
630	    fn write_credentials(&self, _url: &str, _username: &str, _password: &[u8]) -> Task<Result<()>> {
631	        Task::ready(Err(anyhow::anyhow!(
632	            "credential storage is not available on the web"
633	        )))
634	    }
635	
636	    fn read_credentials(&self, _url: &str) -> Task<Result<Option<(String, Vec<u8>)>>> {
637	        Task::ready(Ok(None))
638	    }
639	
640	    fn delete_credentials(&self, _url: &str) -> Task<Result<()>> {
641	        Task::ready(Err(anyhow::anyhow!(
642	            "credential storage is not available on the web"
643	        )))
644	    }
645	
646	    fn keyboard_layout(&self) -> Box<dyn PlatformKeyboardLayout> {
647	        Box::new(WebKeyboardLayout)
648	    }
649	
650	    fn keyboard_mapper(&self) -> Rc<dyn PlatformKeyboardMapper> {
651	        Rc::new(DummyKeyboardMapper)
652	    }
653	
654	    fn on_keyboard_layout_change(&self, callback: Box<dyn FnMut()>) {
655	        self.callbacks.borrow_mut().keyboard_layout_change = Some(callback);
656	    }
657	}
658	
659	/// Maps a `navigator.clipboard.read()` rejection to a [`ClipboardReadError`].
660	///
661	/// Only `NotAllowedError` and `SecurityError` mean the user or browser
662	/// refused access; other rejections (e.g. `DataError`) indicate content the
663	/// clipboard could not represent, where "allow clipboard access" guidance
664	/// would mislead.
665	fn clipboard_read_rejection_error(error: JsValue) -> ClipboardReadError {
666	    match js_error_name(&error).as_deref() {
667	        Some("NotAllowedError") | Some("SecurityError") => {
668	            ClipboardReadError::Denied(js_error_message(&error))
669	        }
670	        _ => ClipboardReadError::UnsupportedContent,
671	    }
672	}
673	
674	async fn read_clipboard_item_blob(
675	    item: &web_sys::ClipboardItem,
676	    mime_type: &str,
677	) -> Result<web_sys::Blob, JsValue> {
678	    let blob = wasm_bindgen_futures::JsFuture::from(item.get_type(mime_type)).await?;
679	    Ok(blob.unchecked_into())
680	}
681	
682	async fn read_clipboard_item_text(
683	    item: &web_sys::ClipboardItem,
684	    mime_type: &str,
685	) -> Result<String, JsValue> {
686	    let blob = read_clipboard_item_blob(item, mime_type).await?;
687	    let text = wasm_bindgen_futures::JsFuture::from(blob.text()).await?;
688	    text.as_string()
689	        .ok_or_else(|| JsValue::from_str("blob text is not a string"))
690	}
691	
692	async fn read_clipboard_item_bytes(
693	    item: &web_sys::ClipboardItem,
694	    mime_type: &str,
695	) -> Result<Vec<u8>, JsValue> {
696	    let blob = read_clipboard_item_blob(item, mime_type).await?;
697	    read_blob_bytes(&blob).await
698	}
699	
700	pub(crate) async fn read_blob_bytes(blob: &web_sys::Blob) -> Result<Vec<u8>, JsValue> {
701	    let buffer = wasm_bindgen_futures::JsFuture::from(blob.array_buffer()).await?;
702	    Ok(js_sys::Uint8Array::new(&buffer).to_vec())
703	}
704	
705	fn js_error_name(error: &JsValue) -> Option<String> {
706	    js_sys::Reflect::get(error, &"name".into())
707	        .ok()
708	        .and_then(|name| name.as_string())
709	}
710	
711	pub(crate) fn js_error_message(error: &JsValue) -> String {
712	    js_sys::Reflect::get(error, &"message".into())
713	        .ok()
714	        .and_then(|message| message.as_string())
715	        .or_else(|| error.as_string())
716	        .unwrap_or_else(|| "unknown browser error".to_string())
717	}
718	
719	fn log_clipboard_entry_error(mime_type: &str, error: &JsValue) {
720	    log::warn!(
721	        "failed to read clipboard entry with type {mime_type}: {}",
722	        js_error_message(error)
723	    );
724	}
725	
726	fn cursor_restore_listeners(
727	    browser_window: &web_sys::Window,
728	    cursor_visible: Rc<Cell<bool>>,
729	    last_cursor_css: Rc<Cell<&'static str>>,
730	) -> Vec<EventListenerHandle> {
731	    let mut handles = Vec::new();
732	    let Some(document) = browser_window.document() else {
733	        return handles;
734	    };
735	
736	    let mut add_listener = |target: &web_sys::EventTarget, event_name: &'static str| {
737	        let browser_window = browser_window.clone();
738	        let cursor_visible = cursor_visible.clone();
739	        let last_cursor_css = last_cursor_css.clone();
740	        handles.push(EventListenerHandle::add(
741	            target,
742	            event_name,
743	            move |_event: JsValue| {
744	                if !cursor_visible.replace(true) {
745	                    set_body_cursor(&browser_window, last_cursor_css.get());
746	                }
747	            },
748	        ));
749	    };
750	
751	    let document_target: &web_sys::EventTarget = document.as_ref();
752	    let window_target: &web_sys::EventTarget = browser_window.as_ref();
753	
754	    add_listener(document_target, "mousemove");
755	    add_listener(document_target, "mouseenter");
756	    add_listener(window_target, "blur");
757	    add_listener(document_target, "visibilitychange");
758	
759	    handles
760	}
761	
762	fn show_graphics_unavailable_message(browser_window: &web_sys::Window, error: &anyhow::Error) {
763	    let Some(document) = browser_window.document() else {
764	        return;
765	    };
766	    let Some(body) = document.body() else {
767	        return;
768	    };
769	    let Ok(message) = document.create_element("p") else {
770	        return;
771	    };
772	    message.set_text_content(Some(&format!(
773	        "Failed to initialize browser graphics: {error}"
774	    )));
775	    body.append_child(&message).ok();
776	}
777	
778	fn set_body_cursor(browser_window: &web_sys::Window, css_cursor: &str) {
779	    if let Some(document) = browser_window.document()
780	        && let Some(body) = document.body()
781	        && let Err(error) = body.style().set_property("cursor", css_cursor)
782	    {
783	        log::warn!("Failed to set cursor style: {error:?}");
784	    }
785	}
