52	struct MainThreadMailbox {
53	    sender: PriorityQueueSender<MainThreadItem>,
54	    receiver: parking_lot::Mutex<PriorityQueueReceiver<MainThreadItem>>,
55	    signal: AtomicI32,
56	}
57	
58	impl MainThreadMailbox {
59	    fn new() -> Self {
60	        let (sender, receiver) = PriorityQueueReceiver::new();
61	        Self {
62	            sender,
63	            receiver: parking_lot::Mutex::new(receiver),
64	            signal: AtomicI32::new(0),
65	        }
66	    }
67	
68	    fn post(&self, priority: Priority, item: MainThreadItem) {
69	        if self.sender.spin_send(priority, item).is_err() {
70	            log::error!("MainThreadMailbox::send failed: receiver disconnected");
71	        }
72	
73	        // TODO-Wasm: Verify this lock-free protocol
74	        let view = self.signal_view();
75	        js_sys::Atomics::store(&view, 0, 1).ok();
76	        js_sys::Atomics::notify(&view, 0).ok();
77	    }
78	
79	    fn drain(&self, window: &web_sys::Window) {
80	        let mut receiver = self.receiver.lock();
81	        loop {
82	            // We need these `spin` variants because we can't acquire a lock on the main thread.
83	            // TODO-WASM: Should we do something different?
84	            match receiver.spin_try_pop() {
85	                Ok(Some(item)) => execute_on_main_thread(window, item),
86	                Ok(None) => break,
87	                Err(_) => break,
88	            }
89	        }
90	    }
91	
92	    fn signal_view(&self) -> js_sys::Int32Array {
93	        let byte_offset = self.signal.as_ptr() as u32;
94	        let memory = js_sys::WebAssembly::Memory::from(wasm_bindgen::memory());
95	        js_sys::Int32Array::new_with_byte_offset_and_length(&memory.buffer(), byte_offset, 1)
96	    }
97	
98	    fn run_waker_loop(self: &Arc<Self>, window: web_sys::Window) {
99	        if !shared_memory_supported() {
100	            log::warn!("SharedArrayBuffer not available; main thread mailbox waker loop disabled");
101	            return;
102	        }
103	
104	        let mailbox = Arc::clone(self);
105	        wasm_bindgen_futures::spawn_local(async move {
106	            let view = mailbox.signal_view();
107	            loop {
108	                js_sys::Atomics::store(&view, 0, 0).expect("Atomics.store failed");
109	
110	                // Items posted between the previous drain and the store above
111	                // set the signal we just cleared, so their notify is lost.
112	                // Drain again after re-arming to avoid missing them.
113	                mailbox.drain(&window);
114	
115	                let result = match js_sys::Atomics::wait_async(&view, 0, 0) {
116	                    Ok(result) => result,
117	                    Err(error) => {
118	                        log::error!("Atomics.waitAsync failed: {error:?}");
119	                        break;
120	                    }
121	                };
122	
123	                let is_async = js_sys::Reflect::get(&result, &JsValue::from_str("async"))
124	                    .ok()
125	                    .and_then(|v| v.as_bool())
126	                    .unwrap_or(false);
127	
128	                // `async: false` means the signal changed between the store and
129	                // the wait ("not-equal"): work has already arrived, so skip
130	                // waiting and drain immediately.
131	                if is_async {
132	                    let promise: js_sys::Promise =
133	                        js_sys::Reflect::get(&result, &JsValue::from_str("value"))
134	                            .expect("waitAsync result missing 'value'")
135	                            .unchecked_into();
136	
137	                    let _ = wasm_bindgen_futures::JsFuture::from(promise).await;
138	                }
139	
140	                mailbox.drain(&window);
141	            }
142	        });
143	    }
144	}
