155	impl WebDispatcher {
156	    pub fn new(browser_window: web_sys::Window, allow_threads: bool) -> Self {
157	        #[cfg(feature = "multithreaded")]
158	        let (background_sender, background_receiver) = PriorityQueueReceiver::new();
159	        #[cfg(not(feature = "multithreaded"))]
160	        let (background_sender, _) = PriorityQueueReceiver::new();
161	
162	        let main_thread_mailbox = Arc::new(MainThreadMailbox::new());
163	
164	        let supports_threads = cfg!(feature = "multithreaded")
165	            && allow_threads
166	            && shared_memory_supported()
167	            && wait_async_supported();
168	
169	        if supports_threads {
170	            main_thread_mailbox.run_waker_loop(browser_window.clone());
171	        } else if cfg!(feature = "multithreaded") && allow_threads {
172	            log::warn!(
173	                "Required WebAssembly threading APIs are unavailable; falling back to single-threaded dispatcher"
174	            );
175	        }
176	
177	        #[cfg(feature = "multithreaded")]
178	        let background_threads = if supports_threads {
179	            let thread_count = browser_window
180	                .navigator()
181	                .hardware_concurrency()
182	                .max(MIN_BACKGROUND_THREADS as f64) as usize;
183	
184	            // TODO-Wasm: Is it bad to have web workers blocking for a long time like this?
185	            (0..thread_count)
186	                .map(|i| {
187	                    let mut receiver = background_receiver.clone();
188	                    wasm_thread::Builder::new()
189	                        .name(format!("background-worker-{i}"))
190	                        .spawn(move || {
191	                            loop {
192	                                let runnable: RunnableVariant = match receiver.pop() {
193	                                    Ok(runnable) => runnable,
194	                                    Err(_) => {
195	                                        log::info!(
196	                                            "background-worker-{i}: channel disconnected, exiting"
197	                                        );
198	                                        break;
199	                                    }
200	                                };
201	
202	                                runnable.run();
203	                            }
204	                        })
205	                        .expect("failed to spawn background worker thread")
206	                })
207	                .collect::<Vec<_>>()
208	        } else {
209	            Vec::new()
210	        };
211	
212	        Self {
213	            main_thread_id: std::thread::current().id(),
214	            background_sender,
215	            main_thread_mailbox,
216	            supports_threads,
217	            #[cfg(feature = "multithreaded")]
218	            _background_threads: background_threads,
