        let capslock = capslock_from_keyboard_event(&event);

        if this.update_modifiers(modifiers, capslock) {
            this.dispatch_input(PlatformInput::ModifiersChanged(ModifiersChangedEvent {
                modifiers,
                capslock,
            }));
